package com.fream.back.domain.order.entity;

import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.sale.entity.Sale;
import com.fream.back.domain.user.entity.User;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;

/**
 * 주문 입찰 엔티티
 */
@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class OrderBid extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id")
    private User user; // 구매자 정보

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private ProductSize productSize; // 구매 대상 상품 사이즈

    private int bidPrice; // 입찰 가격

    @Builder.Default
    @Enumerated(EnumType.STRING)
    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Order order; // 매칭된 구매 엔티티

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Sale sale; // 매칭된 판매 엔티티

    // 즉시 구매 플래그
    @Builder.Default
    @Column(nullable = false)
    private boolean isInstantPurchase = false;

    /**
     * Order와의 양방향 관계를 설정합니다.
     * 기존 관계가 있다면 해제하고 새 관계를 설정합니다.
     *
     * @param order 연결할 Order 객체
     */
    public void assignOrder(Order order) {
        // 기존 관계가 있으면 해제
        if (this.order != null && this.order != order) {
            Order oldOrder = this.order;
            this.order = null;
            if (oldOrder.getOrderBid() == this) {
                oldOrder.assignOrderBid(null);
            }
        }

        // 새 관계 설정
        this.order = order;

        // 매칭 상태로 변경
        if (order != null) {
            this.status = BidStatus.MATCHED;

            // Order 쪽에도 관계 설정
            if (order.getOrderBid() != this) {
                order.assignOrderBid(this);
            }
        }
    }

    /**
     * Sale과의 양방향 관계를 설정합니다.
     *
     * @param sale 연결할 Sale 객체
     */
    public void assignSale(Sale sale) {
        this.sale = sale;
        this.status = BidStatus.MATCHED;
    }

    /**
     * 즉시 구매로 표시합니다.
     */
    public void markAsInstantPurchase() {
        this.isInstantPurchase = true;
    }

    /**
     * 입찰 상태를 업데이트합니다.
     *
     * @param newStatus 새 입찰 상태
     */
    public void updateStatus(BidStatus newStatus) {
        this.status = newStatus;
    }
}package com.fream.back.domain.sale.entity;

import com.fream.back.domain.order.entity.Order;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.user.entity.User;
import com.fream.back.global.entity.BaseTimeEntity;
import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;


@Entity
@Getter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class SaleBid extends BaseTimeEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id")
    private User seller; // 판매자 정보

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "product_size_id")
    private ProductSize productSize; // 판매 대상 상품 사이즈

    private int bidPrice; // 판매자가 원하는 가격

    @Enumerated(EnumType.STRING)
    @Builder.Default
    private BidStatus status = BidStatus.PENDING; // 입찰 상태 (대기 중, 매칭 완료 등)

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "sale_id")
    private Sale sale; // 매칭된 판매 엔티티

    @OneToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "order_id")
    private Order order; // 매칭된 구매 엔티티


    // 즉시 판매 플래그
    @Column(nullable = false)
    @Builder.Default
    private boolean isInstantSale = false;

    public void assignSale(Sale sale) {
        this.sale = sale;
        this.status = BidStatus.MATCHED;
    }

    public void assignOrder(Order order) {
        this.order = order;
        this.status = BidStatus.MATCHED;
    }
    public void markAsInstantSale() {
        this.isInstantSale = true;
    }

    public void updateStatus(BidStatus newStatus) {
        this.status = newStatus;
    }
}

    /**
     * 즉시 구매 입력값을 검증합니다.
     */
    private void validateInstantOrderBidInput(String buyerEmail, Long saleBidId, Long addressId, PaymentRequestDto paymentRequest) {
        if (buyerEmail == null || buyerEmail.trim().isEmpty()) {
            throw new OrderBidAccessDeniedException("구매자 이메일이 없습니다.");
        }
        if (saleBidId == null) {
            throw new SaleBidNotFoundException("판매 입찰 ID가 없습니다.");
        }
        if (addressId == null) {
            throw new InvalidOrderBidDataException("배송지 ID가 없습니다.");
        }
        if (paymentRequest == null) {
            throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
        }
    }

    /**
     * SaleBid를 조회하고 유효성을 검증합니다.
     */
    private SaleBid getSaleBidAndValidate(Long saleBidId) {
        SaleBid saleBid = saleBidQueryService.findById(saleBidId);
        if (saleBid == null) {
            throw new SaleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
        }

        Sale sale = saleBid.getSale();
        if (sale == null) {
            throw new InvalidOrderBidDataException("판매 입찰과 연결된 판매 정보가 없습니다.");
        }

        return saleBid;
    }

    /**
     * 즉시 구매 OrderBid를 생성합니다.
     */
    private OrderBid createInstantOrderBid(Order order, SaleBid saleBid, Sale sale) {
        ProductSize productSize = saleBid.getProductSize();

        OrderBid orderBid = OrderBid.builder()
                .user(order.getUser()) // 구매자
                .productSize(productSize)
                .bidPrice(saleBid.getBidPrice())
                .status(BidStatus.MATCHED) // 즉시 구매는 바로 매칭 상태
                .order(order) // Order와 매핑
                .sale(sale) // 셀러 정보 추가
                .build();

        // 양방향 관계 설정
        orderBid.assignOrder(order);

        // 플래그 설정 및 저장
        orderBid.markAsInstantPurchase();
        return orderBidRepository.save(orderBid);
    }

    /**
     * 주문 입찰 생성 예외를 처리합니다.
     */
    private void handleOrderBidCreationException(Exception e, String operation) {
        if (e instanceof OrderException) {
            throw (OrderException) e;
        }
        log.error("{} 중 오류 발생: {}", operation, e.getMessage(), e);
        throw new OrderBidCreationFailedException(operation + " 중 오류가 발생했습니다: " + e.getMessage(), e);
    }

    /**
     * 주문 입찰을 매칭 상태로 업데이트합니다.
     *
     * @param orderBid 주문 입찰
     * @throws InvalidOrderBidStatusException 주문 입찰 상태가 유효하지 않은 경우
     * @throws OrderBidMatchingFailedException 주문 입찰 매칭 실패 시
     */
    @Transactional
    public void matchOrderBid(OrderBid orderBid) {
        try {
            if (orderBid == null) {
                throw new OrderBidNotFoundException("주문 입찰 정보가 없습니다.");
            }

            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰입니다(ID: " + orderBid.getId() + ")");
            }

            orderBid.updateStatus(BidStatus.MATCHED);
        } catch (Exception e) {
            if (e instanceof OrderException) {
                throw e;
            }
            log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }

    /**
     * 주문 입찰을 삭제합니다.
     *
     * @param orderBidId 주문 입찰 ID
     * @throws OrderBidNotFoundException 주문 입찰을 찾을 수 없는 경우
     * @throws OrderBidAlreadyMatchedException 이미 매칭된 주문 입찰인 경우
     * @throws OrderBidDeletionFailedException 주문 입찰 삭제 실패 시
     */
    @Transactional
    public void deleteOrderBid(Long orderBidId) {
        try {
            // OrderBid 조회
            OrderBid orderBid = orderBidRepository.findById(orderBidId)
                    .orElseThrow(() -> new OrderBidNotFoundException("해당 주문 입찰을 찾을 수 없습니다(ID: " + orderBidId + ")"));

            // Sale과 연결 여부 확인
            if (orderBid.getSale() != null) {
                throw new OrderBidAlreadyMatchedException("주문 입찰이 판매와 연결되어 있어 삭제할 수 없습니다.");
            }

            // 매칭 상태 확인
            if (orderBid.getStatus() == BidStatus.MATCHED) {
                throw new OrderBidAlreadyMatchedException("이미 매칭된 주문 입찰은 삭제할 수 없습니다.");
            }

            // Order와 연결 여부 확인 후 삭제
            if (orderBid.getOrder() != null) {
                orderCommandService.deleteOrder(orderBid.getOrder().getId());
            }

            // OrderBid 삭제
            orderBidRepository.delete(orderBid);
        } catch (Exception e) {
            if (e instanceof OrderException) {
                throw e;
            }
            log.error("주문 입찰 삭제 중 오류 발생: {}", e.getMessage(), e);
            throw new OrderBidDeletionFailedException("주문 입찰 삭제 중 오류가 발생했습니다: " + e.getMessage(), e);
        }
    }
}        // 4. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale) // 연관된 Sale 설정
                .build();

        // 5. SaleBid 저장
        saleBid = saleBidRepository.save(saleBid);

        // 6. Sale에 SaleBid 추가 (연관관계 설정)
        sale.assignSaleBid(saleBid);

        // 7. SaleBid 반환
        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Sale sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);
        // 1. OrderBid 조회
        OrderBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        // 3. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(sale.getSeller()) // Sale의 판매자
                .productSize(sale.getProductSize()) // Sale의 ProductSize
                .bidPrice(orderBid.getBidPrice()) // OrderBid의 입찰 가격 사용
                .status(BidStatus.MATCHED) // 즉시 판매는 바로 매칭 상태
                .sale(sale) // Sale과 매핑
                .order(orderBid.getOrder()) // Order와 매핑
                .build();

        // 양방향 관계 설정
        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid); // Sale과 SaleBid 양방향 연관관계 설정

        // SaleBid 저장
        saleBidRepository.save(saleBid);

        // Sale ID 반환
        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {
        // SaleBid 조회
        SaleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));

        // Order와 연결 여부 확인
        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }

        // Sale과 연결 여부 확인 후 삭제
